// The fake Facebook's stylesheet. Like Comet's StyleX output, class names are opaque atomic-looking hashes
// ("x1a2b3c4"), so MFGA cannot (and must not) key on them; layout reads Facebook's own theme tokens.

import { createHash } from "node:crypto";

const atomic = (key) => `x${createHash("md5").update(`fbfixture:${key}`).digest("hex").slice(0, 7)}`;

/** C.banner -> "x3f9a0c1" (stable per key). */
export const C = new Proxy({}, { get: (_, key) => atomic(String(key)) });

