/** Theme overrides Facebook injects from JS on logged-in pages (header 56px, Facebook's light palette). */
const LOGGED_IN_THEME = `:root, .__fb-light-mode:root, .__fb-light-mode {
  --header-height: 56px;
  --web-wash: #F0F2F5;
  --body-font-family: Segoe UI Historic, Segoe UI, Helvetica, Arial, sans-serif;
  --card-corner-radius: 8px;
}`;

export function appCss() {
  const rules = Object.entries(RULES).map(([key, css]) => `.${atomic(key)}{${css}}`);
  return [
    LOGGED_IN_THEME,
    "html,body{margin:0;padding:0}",
    "body{background:var(--web-wash);color:var(--primary-text);font-family:var(--body-font-family);font-size:var(--body-font-size);line-height:1.3333}",
    "a{color:var(--blue-link);text-decoration:none}",
    "h1,h2,h3,h4,h5{font-size:inherit;margin:0}",
    `.${atomic("tabActive")} svg{color:var(--accent)}`,
    `.${atomic("commentBox")} p{margin:0}`,
    ...rules,
    "@media (max-width:1099px){" + `.${atomic("leftRail")}{display:none}` + "}",
    "@media (max-width:899px){" + `.${atomic("rightRail")}{display:none}` + "}",
  ].join("\n");
}
